export type ProductEditorial = {
  summary: string;
  paragraphs: [string, string];
  benefits: [string, string, string];
  applications: [string, string, string];
  sources: string[];
  researchNote?: string;
};

const globalSource = (path: string) => `https://www.xcmgglobal.com/${path}`;
const chinaSource = (id: string) => `https://www.xcmg.com/product/pro-detail-${id}.htm`;
const brochure = (folder: string, name: string) =>
  `/brochures/catalog/Xcmg pdf/${folder}/${name}.pdf`;

function content(
  summary: string,
  performance: string,
  application: string,
  benefits: ProductEditorial["benefits"],
  applications: ProductEditorial["applications"],
  sources: string[],
  researchNote?: string,
): ProductEditorial {
  return { summary, paragraphs: [performance, application], benefits, applications, sources, researchNote };
}

