export function productEditorialKey(model: string): string {
  return model.replace(/\s+/g, "").replace(/-/g, "_").replace(/\//g, "").toUpperCase();
}

export function productEditorialForModel(model: string): ProductEditorial | undefined {
  return productEditorialByModel[productEditorialKey(model)];
}
